import http.client, json, os, time, uuid
BOOT = uuid.uuid4().hex
READY = None
if os.environ.get('PROBE_SUBSCRIPTIONS'):
    for attempt in range(160):
        try:
            connection = http.client.HTTPConnection('127.0.0.1',4243,timeout=2)
            connection.request('GET','/ready')
            response = connection.getresponse()
            READY = json.loads(response.read())
            connection.close()
            if response.status == 200:
                break
        except (OSError,ValueError):
            pass
        time.sleep(.05)
    else:
        raise RuntimeError('Extension Init barrier expired')

def handler(event, context):
    print('FUNCTION_MARKER '+event['marker'],flush=True)
    if READY:
        connection = http.client.HTTPConnection('127.0.0.1',4243,timeout=4)
        connection.request('POST','/control',json.dumps({'marker':event['marker']}))
        response = connection.getresponse()
        response.read()
        connection.close()
    for descriptor, text in event.get('writes', []):
        os.write(descriptor, text.encode())
        time.sleep(.05)
    time.sleep(event.get('sleep',1))
    if event.get('fail'):
        raise ValueError('Native platform schema control')
    return {'marker':event['marker'],'boot':BOOT,'extension':READY,'request_id':context.aws_request_id}
